"""Editable chapter-four story source; writes a separate add-on to the existing journal."""
from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
scenes=[
('失声的琴房','救出睦子米','中级奶娃与凑企鹅封锁了琴房。菲比、糯糯、Doro、咕嘎仍可与坤坤一起出战；Q币企鹅的合同不覆盖沼泽。清除全部波次后救出睦子米。','mutsumi','睦子米抱紧粉色大提琴：“我听见你来了。它们把大家的声音锁在不同的地方……让我跟你一起找。”解锁睦子米。稍后将收到菲比的来电。','粉琴的普通声波覆盖一片敌人；F环形共鸣能直接清除幼体。优先闪开投石，再逐个拆解中级守卫。'),
('黄白和弦','救出soyo狸','白色琴弦从右门延伸到囚笼。新出现的天素罗幼体会蜷缩蓄力，再向前弹射；看准预警横向移动。','soyo','soyo狸：“别再把谁落下了。我的和弦可以穿过一整排敌人。”黄白大提琴已解锁，F直线终曲能击倒中级体。','把追兵引到同一条直线上，再用soyo的F。弹射有蓄力，避免沿红线往后退。'),
('无法停止的歌','救出千早爱音','歌声仍在囚笼中断续响起。天素罗中级体开始聚能直线光波；奶娃和凑企鹅已是完全体。','anon','爱音：“唱得不够好，也不能停在这里。”爱音加入队伍，自动用声音攻击附近敌人，削弱它们的行动与伤害。','爱音对天素罗及伪罗的声波伤害翻倍强化。先躲开直线光波，再进声波范围压制。'),
('看清杂音','取回爱音的眼镜','眼镜被锁在舞台的封印里。守卫沿用完全体阵容；清除所有波次，解开眼镜封印。','anon','爱音戴上眼镜：“这次看清了，不会再错过你们的信号。”声波伤害与范围进一步提升，形态自动切换。','先用范围武器清理幼体，再处理完全体。眼镜形态属于爱音的升级，不占额外队伍位置。'),
('同化的回声','解锁爱音奶龙形态','天素罗完全体出现，还会召来奶娃和凑企鹅完全体。不要陷在召唤物中间，优先压制召唤者。','anon','新的和声让爱音变成奶龙形态，声波可以把奶娃同化为队友。凑企鹅放下石头：“至少这一次，我跟你们走。”它将以自主队友身份随行。随后播放“天素罗的开始”。同时获得破甲战歌：按5或在背包使用，30秒内攻击造成999真伤，每次关卡挑战只能使用一次。','同化最多保留4名队友，包含完全体奶娃；超过上限时仍造成伤害。凑企鹅暂时帮忙，不成为可选人物。'),
('真身与伪装','夺回共振架子鼓','真正的天素罗没有手。之前展示手口聚能的身影竟是伪罗！天素罗伪罗完全体会召来天素罗的全部阶段。','soyo','伪装被揭穿，架子鼓重归舞台。获得大范围、高伤害、带减速的共振架子鼓。凑企鹅仍在旁边提供火力。随后播放“天素罗伪罗”。','优先击败伪罗，切断增援。鼓由音乐角色装备；坤坤继续使用篮球。'),
('两分钟的排练','坚持超过两分钟并清场','营地需要时间修复乐器。这里没有完全体，只有大量中级敌人。坚持121秒后停止增援，再清除剩余敌人。','ikun','坤坤转了转篮球：“节拍还行。下一场，可别有人临时变调。”凑企鹅站在暗处，没有回答。','这是升级与整理补给的间歇。计时结束不等于自动胜利，还需要清场。医护、商人与工匠各有不同作用。'),
('背叛的指挥者','将凑企鹅打至10%生命','凑企鹅突然夺走指挥权，控制天素罗和伪罗攻击你。它承认这场分裂由自己策划，所谓帮忙只是靠近舞台的借口。','penguin_full','凑企鹅只剩一成生命，扔下指挥棒冲进绿门：“这点掌声就想让我谢幕？下一幕，你们一个也别想走！”它逃走了。获得音乐指挥棒，右侧出口开启。','凑企鹅的生命与攻击提高。压低它的生命就能迫使它逃走，不必把所有召唤物都打完。'),
('被操纵的真相','击败强化凑企鹅，解救天素罗','凑企鹅再次强化，集结所有完全体。天素罗仍受控制；击败首领和所有守卫，才能解除囚笼。','soyo','天素罗：“对不起……那些伤害不是我想做的。”soyo狸将天素罗吞入金色音符之中，以幻想式融合接纳它的力量，成为完全体。救援记录已解锁，soyo固定持有音乐指挥棒。','先处理能够召唤的首领，再清场。天素罗作为救援与融合进度解锁，力量由soyo继承。'),
('最后的合奏','召集三位演奏者，保护合奏击败终极凑企鹅','先切换soyo狸，持音乐指挥棒按F三次，依次释放睦子米、爱音、soyo。三人就位后，只能操控坤坤。保护她们完成五波递增战斗。三人每8秒释放合击音波，凑企鹅最终体第三波登场，最后一波用合击击败它。','ikun','合击唤醒了凑企鹅的记忆：它原来也是乐队成员，才是真正的主唱。回忆结束，它向受伤的同伴道歉，带着愧疚与悲伤离开。第四章落幕，通关音乐响起。','三人部署完毕获得98%减伤护盾。乐队音波命中的所有奶娃都会转为友军，主动攻击其它敌人；其它幼体直接倒下，中级体最多承受两次合击。第三、四波分别削弱首领并清场，第五波完成最后合击。保护三位固定站位的成员。')]
data={}
for n,(title,goal,intro,speaker,outro,hint) in enumerate(scenes,28):
    def choices(text):
        return [{'id':'act','text':'我准备好了，开始行动','speaker':'ikun','emotion':'proud','reply':text}, {'id':'plan','text':'先听战术和救援要点','speaker':'ikun','emotion':'dialogue','reply':hint}]
    data[str(n)]={'title':title,'goal':goal,'npc':'舞台联络员·小弦','task':goal+'。'+hint,'clue':hint,'briefing':intro,'intro':{'speaker':'ikun','emotion':'battle','text':intro,'choices':choices('沿道路进入战场，优先识别预警。完成任务后右门才会开启。')},'outro':{'speaker':speaker,'emotion':'angry' if n==35 else 'victory','text':outro,'choices':[{'id':'continue_story','text':'记下这段经历，继续','speaker':'ikun','emotion':'dialogue','reply':'救援进展已保存，下一扇彩门解封。' if n<37 else '第四章的合奏已经完成。回到主图整理队伍吧。'}]}}
(root/'Story/Data/chapter4.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf8')
